package com.learnagent.memory;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="knowledge_nodes")public class KnowledgeNode{@Id private UUID id;@Column(name="course_id",nullable=false)private UUID courseId;@Column(nullable=false)private String name;@Column(name="normalized_key",nullable=false)private String normalizedKey;@Column(nullable=false)private double mastery;@Column(nullable=false)private double retrievability;@Column(name="forgetting_risk",nullable=false)private double forgettingRisk;@Column(name="source_json",nullable=false,columnDefinition="text")private String sourceJson;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected KnowledgeNode(){}public KnowledgeNode(UUID course,String name,String key,String source){id=UUID.randomUUID();courseId=course;this.name=name;normalizedKey=key;sourceJson=source;retrievability=1;updatedAt=Instant.now();}public void update(double mastery,double retrievability,String source){this.mastery=mastery;this.retrievability=retrievability;forgettingRisk=1-retrievability;if(source!=null&&!source.isBlank()&&!"[]".equals(source))sourceJson=source;updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getCourseId(){return courseId;}public String getName(){return name;}public double getMastery(){return mastery;}public double getRetrievability(){return retrievability;}public double getForgettingRisk(){return forgettingRisk;}public String getSourceJson(){return sourceJson;}}
